*{box-sizing:border-box}html,body{margin:0;min-height:0;background:transparent!important;color:var(--pc-text);font-family:Arial,Helvetica,sans-serif}body{padding:0}.pc-page{width:260px;max-width:100%;margin:0 auto}.pc-widget{display:grid;gap:7px}.pc-section{display:grid;gap:5px}.pc-head{display:flex;align-items:center;justify-content:space-between;gap:5px;min-width:0}.pc-title{min-width:0;color:var(--pc-gold);font-size:13px;font-weight:900;white-space:nowrap}.pc-links{display:flex;gap:3px}.pc-links a{display:inline-flex;align-items:center;min-height:20px;padding:3px 6px;border:1px solid color-mix(in srgb,var(--pc-gold) 44%,var(--pc-border));border-radius:7px;background:color-mix(in srgb,var(--pc-gold) 7%,var(--pc-chip));color:var(--pc-gold);font-size:8px;font-weight:900;text-decoration:none}.pc-tabs{display:inline-flex;gap:1px;padding:2px;border:1px solid color-mix(in srgb,var(--pc-gold) 24%,var(--pc-border));border-radius:999px;background:var(--pc-selector)}.pc-tab{all:unset;cursor:pointer;min-width:35px;padding:3px 5px;border-radius:999px;color:var(--pc-muted);font-size:8px;font-weight:900;text-align:center}.pc-tab.is-active{background:var(--pc-selector-active);color:#17110a}.pc-grid{display:grid;width:260px;grid-template-columns:repeat(2,minmax(0,1fr));gap:6px}.pc-empty{grid-column:1/-1;padding:12px 6px;border:1px dashed var(--pc-border);border-radius:9px;color:var(--pc-muted);font-size:9px;text-align:center}.pc-card{position:relative;display:block;min-width:0;overflow:hidden;border:1px solid var(--pc-border);border-radius:10px;background:var(--pc-card);color:inherit;text-decoration:none;box-shadow:0 4px 12px var(--pc-shadow)}.pc-visual{position:relative;display:grid;place-items:center;height:82px;padding:8px;overflow:hidden;background:radial-gradient(circle at 50% 38%,rgba(255,255,255,.055),transparent 48%),var(--pc-visual);border-bottom:1px solid color-mix(in srgb,var(--pc-border) 58%,transparent)}.pc-club-logo{display:block;width:65px;height:65px;object-fit:contain;filter:drop-shadow(0 4px 7px rgba(0,0,0,.16))}.pc-logo-fallback{display:grid;place-items:center;width:60px;height:60px;border:1px solid var(--pc-border);border-radius:15px;background:var(--pc-chip);color:var(--pc-gold);font-size:22px;font-weight:900}.pc-badge,.pc-priority{position:absolute;top:5px;display:inline-flex;align-items:center;max-width:calc(100% - 12px);padding:3px 6px;overflow:hidden;border:1px solid color-mix(in srgb,var(--pc-gold) 38%,transparent);border-radius:999px;background:color-mix(in srgb,var(--pc-card) 84%,transparent);color:var(--pc-gold);font-size:9.5px;font-weight:900;line-height:1.05;white-space:nowrap;text-overflow:ellipsis}.pc-badge{left:5px}.pc-badge.friendly{border-color:color-mix(in srgb,var(--pc-green) 38%,transparent);color:var(--pc-green)}.pc-priority{right:5px;border-color:color-mix(in srgb,var(--pc-red) 42%,transparent);color:var(--pc-red)}.pc-info{display:grid;gap:2px;padding:6px 6px 7px;text-align:center}.pc-line{display:flex;align-items:baseline;justify-content:center;gap:4px;min-width:0;overflow:hidden;white-space:nowrap}.pc-primary{font-size:10.8px;font-weight:900;line-height:1.25}.pc-secondary{color:var(--pc-muted);font-size:10px;font-weight:800;line-height:1.25}.pc-red{color:var(--pc-red)}.pc-gold{color:var(--pc-gold)}.pc-green{color:var(--pc-green)}.pc-speed-icon{width:59px;height:59px;color:#79a65a;filter:drop-shadow(0 4px 7px rgba(0,0,0,.17))}.pc-speed-icon.blitz{color:#f0c419}.pc-speed-icon.bullet{color:#b39b79}.pc-footer{text-align:center}.pc-footer a{display:flex;align-items:center;justify-content:center;min-height:27px;padding:4px 7px;border:1px solid color-mix(in srgb,var(--pc-gold) 48%,var(--pc-border));border-radius:7px;background:color-mix(in srgb,var(--pc-gold) 8%,var(--pc-chip));color:var(--pc-gold);font-size:11.5px;font-weight:900;text-decoration:none}
