<body>
<main class="pc-page"><div class="pc-widget">
<section class="pc-section"><header class="pc-head"><div class="pc-title">⚔️ Arenas ⚔️</div><nav class="pc-links"><a href="https://www.chess.com/clubs/currentevents/promote-to-king?type=multi-club-arena" target="_blank" rel="noopener">On-going</a><a href="https://www.chess.com/clubs/upcomingevents/promote-to-king?type=multi-club-arena" target="_blank" rel="noopener">Upcoming</a></nav></header><div class="pc-grid" data-arenas><div class="pc-empty">Loading arenas…</div></div></section>
<section class="pc-section"><header class="pc-head"><div class="pc-title">⚔️ Daily Matches ⚔️</div><nav class="pc-tabs"><button class="pc-tab" type="button" data-filter="league">League</button><button class="pc-tab" type="button" data-filter="friendly">Friendly</button></nav></header><div class="pc-grid" data-daily><div class="pc-empty">Loading matches…</div></div><div class="pc-footer"><a href="https://www.promotetoking.org/" target="_blank" rel="noopener">Open P2K match selection assistant</a></div></section>
</div></main>
<script>
(async()=>{"use strict";
const CORE=window.P2K_EVENTS_SHOWCASE_CORE,SITE=()=>window.P2K_SITE_CONFIG||{},esc=CORE?.escapeHTML||((v)=>String(v??""));
const arenasHost=document.querySelector("[data-arenas]"),dailyHost=document.querySelector("[data-daily]");let matches=[],filter="league",arenas=[];
function initials(name){return(String(name||"?").trim().split(/\s+/).filter(Boolean).slice(0,2).map(w=>w[0]||"").join("")||"?").toUpperCase()}
function needClass(count){const n=Number(count);return !Number.isFinite(n)?"pc-gold":n<=0?"pc-green":n>=8?"pc-red":"pc-gold"}
function chooseFilter(rows){return rows.some(m=>m.joinable!==false&&m.category==="league")?"league":rows.some(m=>m.joinable!==false&&m.category==="friendly")?"friendly":"league"}
function opponentSlug(match){const p=CORE.findClubTeam(match?.detail),o=CORE.findOpponentTeam(match?.detail,p);for(const value of [o?.["@id"],o?.url]){const hit=String(value||"").match(/\/club\/([^/?#]+)/i);if(hit)return decodeURIComponent(hit[1]);}return""}
async function addLogo(match){const slug=opponentSlug(match);if(!slug||!window.P2K_API_CLIENT?.json)return match;try{const club=await window.P2K_API_CLIENT.json(`https://api.chess.com/pub/club/${encodeURIComponent(slug)}`,{attempts:SITE().api?.defaultAttempts||3,priority:"foreground"});return{...match,opponentLogo:String(club?.icon||club?.image||"")}}catch(_){return match}}
function matchCard(match){const urgency=CORE.startUrgency(match.startTime),count=Number.isFinite(Number(match.recruitment?.count))?Number(match.recruitment.count):null,need=count===null?"Need ?":count===0?"Need ✓":`Need ${count}`,badge=match.category==="league"?((match.leagueAcronyms||[]).join("/")||"League"):"Friendly",logo=match.opponentLogo?`<img class="pc-club-logo" src="${esc(match.opponentLogo)}" alt="${esc(match.opponentName||"Opponent")}">`:`<div class="pc-logo-fallback">${esc(initials(match.opponentName))}</div>`,start=CORE.formatStartCompact(match.startTime),time=CORE.timePerMoveCompactLabel(match.timePerMove)||"—",rating=match.ratingLabel||"Open",startClass=urgency.level==="urgent"?"pc-red":urgency.level==="soon"?"pc-gold":"";return`<a class="pc-card" href="${esc(match.url)}" target="_blank" rel="noopener"><div class="pc-visual">${logo}<span class="pc-badge${match.category==="friendly"?" friendly":""}">${esc(badge)}</span>${match.urgent?'<span class="pc-priority">Priority</span>':""}</div><div class="pc-info"><div class="pc-line pc-primary"><span class="${startClass}">${esc(start)}</span><span>·</span><span class="${needClass(count)}">${esc(need)}</span></div><div class="pc-line pc-secondary"><span>${esc(time)}</span><span>·</span><span>${esc(rating)}</span></div></div></a>`}
function renderDaily(){document.querySelectorAll("[data-filter]").forEach(b=>b.classList.toggle("is-active",b.dataset.filter===filter));const visible=matches.filter(m=>m.joinable!==false&&m.category===filter).slice(0,4);dailyHost.innerHTML=visible.map(matchCard).join("")||'<div class="pc-empty">No open priority match in this category.</div>'}
function arenaTiming(arena,now=Date.now()){const start=Date.parse(arena?.startAt||""),duration=Number(arena?.durationMinutes);if(!Number.isFinite(start)||!Number.isFinite(duration)||duration<=0)return null;const end=start+duration*60000;if(now>=end)return null;return{start,end,phase:now<start-3600000?"upcoming":now<start?"registration":"ongoing"}}
function speed(value){const raw=String(value||"").toLowerCase();const hit=raw.match(/(\d+(?:\.\d+)?)\s*(?:\+|\||\/)\s*(\d+(?:\.\d+)?)/);const est=hit?Number(hit[1])+Number(hit[2])*40/60:Number(raw);if(raw.includes("bullet")||Number.isFinite(est)&&est<3)return"bullet";if(raw.includes("blitz")||Number.isFinite(est)&&est<10)return"blitz";return"rapid"}
function speedIcon(kind){if(kind==="bullet")return'<svg class="pc-speed-icon bullet" viewBox="0 0 120 120"><path fill="currentColor" d="M20 72h52c18 0 30-10 30-24S90 24 72 24H59c-3 0-6 2-7 5L39 66c-1 4 2 6 6 6h27z"/></svg>';if(kind==="blitz")return'<svg class="pc-speed-icon blitz" viewBox="0 0 120 120"><path fill="currentColor" d="M68 8 24 66h29l-8 46 50-65H65z"/></svg>';return'<svg class="pc-speed-icon" viewBox="0 0 120 120"><circle cx="60" cy="62" r="42" fill="none" stroke="currentColor" stroke-width="10"/><path d="M60 38v26l19 12" fill="none" stroke="currentColor" stroke-width="10" stroke-linecap="round"/></svg>'}
function arenaCard(arena,timing){const status=timing.phase==="upcoming"?"Upcoming":timing.phase==="registration"?"Registration":"On-going",date=new Intl.DateTimeFormat("en-GB",{day:"numeric",month:"short",hour:"2-digit",minute:"2-digit",hour12:false}).format(new Date(timing.start));return`<a class="pc-card" href="${esc(arena.link)}" target="_blank" rel="noopener"><div class="pc-visual">${speedIcon(speed(arena.timeControl))}<span class="pc-badge">${esc(status)}</span></div><div class="pc-info"><div class="pc-line pc-primary pc-gold">${esc(date)}</div><div class="pc-line pc-secondary"><span>${esc(arena.duration||"—")}</span><span>·</span><span>${esc(arena.timeControl||"—")}</span></div></div></a>`}
function renderArenas(){const now=Date.now(),visible=arenas.map(a=>({a,t:arenaTiming(a,now)})).filter(x=>x.a?.active===true&&x.a?.name&&x.a?.link&&x.t).sort((a,b)=>a.t.start-b.t.start).slice(0,2);arenasHost.innerHTML=visible.map(x=>arenaCard(x.a,x.t)).join("")||'<div class="pc-empty">No active non-expired arena configured.</div>'}
async function load(){if(!CORE)throw Error("Events Showcase core unavailable.");const stateResponse=await fetch("api.php?action=state",{credentials:"same-origin",cache:"no-store"}),state=await stateResponse.json();if(!stateResponse.ok||state?.ok===false)throw Error(state?.error?.message||`HTTP ${stateResponse.status}`);arenas=Array.isArray(state.arenas)?state.arenas:[];renderArenas();const catalogResult=await CORE.loadCatalog(),byId=new Map((catalogResult.matches||[]).map(m=>[String(m.matchId),m])),selected=(state.items||[]).filter(i=>i?.enabled!==false).map(i=>{const m=byId.get(String(i.matchId));return m?{...m,urgent:i?.urgent===true}:null}).filter(Boolean);matches=await CORE.enrichMatches(selected.slice(0,12));matches=await Promise.all(matches.map(addLogo));filter=chooseFilter(matches);renderDaily()}
document.querySelectorAll("[data-filter]").forEach(button=>button.addEventListener("click",()=>{filter=button.dataset.filter;renderDaily()}));
try{await load()}catch(error){console.error(error);dailyHost.innerHTML='<div class="pc-empty">Priority matches are temporarily unavailable.</div>';arenasHost.innerHTML='<div class="pc-empty">Arena data is temporarily unavailable.</div>'}
})();
</script>
</body>
